const { useState } = React;

function App() {
  const [page, setPage] = useState("landing");
  const [message, setMessage] = useState("");

  const handleDownloadClick = () => {
    setMessage("Coming soon");
  };

  const handleBackClick = () => {
    setPage("landing");
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body,html,#root {
          margin: 0;
          padding: 0;
          height: 100%;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fff;
          color: #222;
        }
        .container {
          max-width: 400px;
          margin: 0 auto;
          padding: 16px;
          display: flex;
          flex-direction: column;
          align-items: center;
          min-height: 100vh;
          justify-content: center;
          text-align: center;
        }
        img.hero {
          width: 100%;
          height: auto;
          border-radius: 12px;
          object-fit: cover;
          margin-bottom: 16px;
        }
        h1 {
          font-weight: 700;
          font-size: 2.5rem;
          margin: 0 0 8px 0;
          letter-spacing: 0.05em;
        }
        p.tagline {
          font-size: 1rem;
          color: #555;
          margin: 0 0 24px 0;
          line-height: 1.4;
          min-height: 3.2em;
        }
        button {
          width: 100%;
          padding: 14px 0;
          margin-bottom: 12px;
          font-size: 1.1rem;
          border-radius: 24px;
          border: 2px solid #007bff;
          background: #007bff;
          color: white;
          cursor: pointer;
          transition: background-color 0.3s ease, color 0.3s ease;
          user-select: none;
        }
        button.secondary {
          background: transparent;
          color: #007bff;
        }
        button:hover {
          background-color: #0056b3;
          border-color: #0056b3;
          color: white;
        }
        button.secondary:hover {
          background-color: #007bff;
          color: white;
        }
        .features {
          display: flex;
          justify-content: space-around;
          margin-top: 24px;
          width: 100%;
          max-width: 320px;
        }
        .feature-icon {
          width: 48px;
          height: 48px;
          border-radius: 50%;
          border: 2px solid #007bff;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 24px;
          color: #007bff;
          user-select: none;
        }
        .demo-page {
          padding: 16px;
          max-width: 400px;
          margin: 0 auto;
          text-align: center;
        }
        .demo-page h2 {
          font-size: 2rem;
          margin-bottom: 16px;
        }
        .demo-page p {
          font-size: 1rem;
          color: #444;
          margin-bottom: 24px;
        }
        .alert {
          margin-bottom: 16px;
          color: #d9534f;
          font-weight: 600;
          font-size: 1rem;
        }
      `}</style>

      {page === "landing" && (
        <main className="container" role="main">
          <img
            src="/runtime/photos/fitness.jpg"
            alt="FitTrack app hero"
            className="hero"
          />
          <h1>FitTrack</h1>
          <p className="tagline">Track your fitness journey with ease and motivation.</p>

          {message && (
            <div role="alert" className="alert">
              {message}
            </div>
          )}

          <button onClick={handleDownloadClick} aria-label="Download app">
            Download app
          </button>

          <section className="features" aria-label="App features">
            <div className="feature-icon" aria-hidden="true" title="Track Progress">
              &#128200;
            </div>
            <div className="feature-icon" aria-hidden="true" title="Fast Performance">
              &#9889;
            </div>
            <div className="feature-icon" aria-hidden="true" title="Energy Boost">
              &#9889;
            </div>
          </section>
        </main>
      )}

      {page === "demo" && (
        <main className="demo-page" role="main">
          <h2>FitTrack Demo</h2>
          <p>Welcome to the FitTrack demo page. Here you can see how the app works.</p>
          <button onClick={handleBackClick} aria-label="Back to landing page">
            Back
          </button>
        </main>
      )}
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

